root = pathlib.Path(__file__).resolve().parents[4]
output = root / "build" / "remaining-runtime"
output.mkdir(parents=True, exist_ok=True)
for name, code in FIXTURES.items():
    target = output / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(code, encoding="utf-8")
java = pathlib.Path(os.environ["JAVA_HOME"]) / "bin"
json_jar = sys.argv[1]
production = root / "extensions/nuvio-remaining-episodes/src/main/java/software/santodan/extension/nuvioremaining"
sources = [str(p) for p in output.rglob("*.java")] + [str(p) for p in production.glob("*.java")]
subprocess.run([str(java / "javac"), "-cp", json_jar, "-d", str(output / "classes"), *sources], check=True)
subprocess.run([str(java / "java"), "-cp", str(output / "classes") + os.pathsep + json_jar, "Check"], check=True)
